const token=location.pathname.split('/').filter(Boolean).pop()||'';
const UUID_RE=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if(!UUID_RE.test(token)){document.body.innerHTML='<main class="wrap"><div class="panel"><h2>Mesa inválida</h2><p class="muted">Escaneie o QR Code da mesa.</p></div></main>';throw new Error('token inválido');}
let categorias=[],produtos=[],cart=[],totalDevido=0,cartOpen=false,sessaoData=null,sessaoOpen=false,clienteNome='';
let lastStatusMap={};
function lqPageId(){try{let id=sessionStorage.getItem('lq-page-id');if(!id){id=(Math.random().toString(36).slice(2)+Date.now().toString(36));sessionStorage.setItem('lq-page-id',id);}return id;}catch(_){return 'local';}}
function lqGetJson(key,fallback){try{const raw=sessionStorage.getItem(key);if(!raw)return fallback;return JSON.parse(raw);}catch(_){return fallback;}}
function lqSetJson(key,val){try{sessionStorage.setItem(key,JSON.stringify(val));}catch(_){}}
function lqLoadContaOpen(){const token=(location.pathname.split('/').filter(Boolean).pop())||'';return lqGetJson('lq-conta-open-'+token+'-'+lqPageId(),[]);}
function lqSaveContaOpen(ids){const token=(location.pathname.split('/').filter(Boolean).pop())||'';lqSetJson('lq-conta-open-'+token+'-'+lqPageId(),Array.from(ids||[]));}
function getClienteNome(){if(clienteNome)return clienteNome;try{clienteNome=sessionStorage.getItem('lq-cliente-nome-'+token)||'';}catch(_){}return clienteNome;}
function setClienteNome(nome){clienteNome=String(nome||'').trim().slice(0,80);try{sessionStorage.setItem('lq-cliente-nome-'+token,clienteNome);}catch(_){}}
function ensureClienteNome(){return new Promise((resolve)=>{if(getClienteNome())return resolve(getClienteNome());const gate=document.getElementById('nameGate');const input=document.getElementById('clienteNomeInput');const btn=document.getElementById('clienteNomeBtn');gate.hidden=false;setTimeout(()=>input.focus(),50);const done=()=>{const n=(input.value||'').trim();if(!n){input.focus();return;}setClienteNome(n);gate.hidden=true;fetch('/api/mesas/'+token+'/checkin',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({clienteNome:n})}).catch(()=>{});resolve(n);};btn.addEventListener('click',done);input.addEventListener('keydown',(e)=>{if(e.key==='Enter'){e.preventDefault();done();}});});}
const STATUS_LABEL={recebido:'Na cozinha',em_producao:'Preparando',concluido:'Pronto',entregue:'Entregue'};
const STATUS_TOAST={recebido:'Pedido chegou na cozinha',em_producao:'Pedido em preparo',concluido:'Pedido pronto — o garçom já vai levar',entregue:'Pedido entregue na mesa'};
const br=n=>'R$ '+Number(n).toFixed(2).replace('.',',');
const esc=(s)=>{if(window.SafeDOM&&typeof SafeDOM.escapeHtml==='function')return SafeDOM.escapeHtml(s);return String(s??'').replace(/[&<>"']/g,ch=>({'&':'&','<':'<','>':'>','"':'"',"'":'&#039;'}[ch]));};
function cartCount(){return cart.reduce((s,i)=>s+i.qty,0);}
function cartTotal(){return cart.reduce((s,i)=>s+itemTotal(i),0);}
function updateCartPill(){const n=cartCount();const badge=document.getElementById('cartBadge');if(badge){badge.textContent=n;badge.classList.toggle('show',n>0);}const total=totalDevido||(sessaoData&&sessaoData.totalDevido)||0;const contaBadge=document.getElementById('contaBadge');if(contaBadge){contaBadge.textContent=total>0?'•':'$';contaBadge.classList.toggle('show',total>0||(sessaoData&&(sessaoData.pedidos||[]).length>0));}}
function showToast(message,ms=1800){const toast=document.getElementById('toast');if(!toast)return;toast.textContent=message;toast.classList.add('show');clearTimeout(showToast._t);showToast._t=setTimeout(()=>toast.classList.remove('show'),ms);}
function bounceBurger(){const btn=document.getElementById('burgerBtn');if(!btn)return;btn.classList.remove('pop');void btn.offsetWidth;btn.classList.add('pop');clearTimeout(bounceBurger._t);bounceBurger._t=setTimeout(()=>btn.classList.remove('pop'),600);}
function productNeedsCustom(p){return !!((p.adicionais&&p.adicionais.length)||(p.removiveis&&p.removiveis.length));}
function productIsEscolha(p,catNome){if(!p||!(p.adicionais&&p.adicionais.length))return false;const cat=String(catNome||p._catNome||'').toLowerCase();if(/bebida|drink|refri|suco|agua|cerveja|energ|dose|long\s*neck|caipirinha|gin|doses/.test(cat))return true;return !(p.removiveis&&p.removiveis.length);}
function itemKey(productId,additions,removals,note){return productId+'|'+[...additions].map(a=>a.id).sort().join(',')+'|'+(removals||[]).slice().sort().join(',')+'|'+(note||'');}
function itemTotal(i){const p=produtos.find(x=>x.id===i.productId);if(!p)return 0;const add=i.additions.reduce((s,a)=>s+Number(a.preco||0),0);return (Number(p.preco)+add)*i.qty;}
function notifyStatusChanges(pedidos){if(!Array.isArray(pedidos))return;const next={};for(const p of pedidos){next[p.id]=p.status;const prev=lastStatusMap[p.id];if(prev&&prev!==p.status){const msg=STATUS_TOAST[p.status]||('Pedido #'+p.id+' → '+(STATUS_LABEL[p.status]||p.status));showToast('#'+p.id+' · '+msg,3200);}}lastStatusMap=next;}
async function loadSessao(){try{const r=await fetch('/api/mesas/'+token+'/sessao');if(!r.ok)return;const s=await r.json();sessaoData=s;window.sessaoData=s;totalDevido=s.totalDevido||0;notifyStatusChanges(s.pedidos||[]);document.getElementById('mesaDesk').textContent='Mesa '+s.mesa+(getClienteNome()?' · '+getClienteNome():' · Cardápio');updateCartPill();if(sessaoOpen){const openIds=[...document.querySelectorAll('.pedido-block details[open][data-pedido-id]')].map(d=>String(d.getAttribute('data-pedido-id')));if(openIds.length||!window._contaOpenPedidos){window._contaOpenPedidos=openIds.length?openIds:(window._contaOpenPedidos||[]);}openSessao();}}catch(_){}}
async function cancelarPedido(pedidoId){if(!confirm('Cancelar o pedido #'+pedidoId+'? Só dá enquanto a cozinha ainda não começou o preparo.'))return;try{const r=await fetch('/api/mesas/'+token+'/pedidos/'+pedidoId,{method:'DELETE'});const d=await r.json().catch(()=>({}));if(!r.ok){alert(d.error||'Não foi possível cancelar');return;}showToast('Pedido #'+pedidoId+' cancelado',2800);await loadSessao();}catch(e){alert('Falha de rede');}}
function iniciarEdicaoPedido(pedidoId){const s=sessaoData||{};const p=(s.pedidos||[]).find(x=>Number(x.id)===Number(pedidoId));if(!p||p.status!=='recebido'){alert('Só é possível editar antes da cozinha começar o preparo.');return;}cart=[];for(const it of (p.itens||[])){const productId=it.produtoId||it.produto_id;const additions=(it.adicionais||[]).map(a=>({id:a.id,nome:a.nome,preco:Number(a.preco||0)}));const removals=it.remocoes||it.removals||[];const note=it.observacao||'';const key=itemKey(productId,additions,removals,note);cart.push({key,productId,qty:it.quantidade||1,additions,removals,note,_editPedidoId:pedidoId});}window._editandoPedidoId=pedidoId;updateCartPill();closeModal();openCart();showToast('Edite o pedido e toque em Salvar alterações',3500);}
function openSessao(){sessaoOpen=true;cartOpen=false;const prevSheet=document.querySelector('.modal-sheet.conta-sheet');if(prevSheet)window._contaSheetScroll=prevSheet.scrollTop;const s=sessaoData||{pedidos:[],totalDevido:0,mesa:'—'};const pedidos=s.pedidos||[];const openIds=new Set((window._contaOpenPedidos&&window._contaOpenPedidos.length)?window._contaOpenPedidos:lqLoadContaOpen());document.querySelectorAll('.pedido-block details[open][data-pedido-id]').forEach(function(d){openIds.add(String(d.getAttribute('data-pedido-id')));});const blocks=pedidos.length?pedidos.slice().reverse().map(p=>{const itens=(p.itens||[]).map(it=>`<div class="pedido-item"><div><b>${it.quantidade}× ${esc(it.nome)}</b></div><b>${br(it.totalLinha||0)}</b></div>`).join('');const editado=p.editadoEm||p.editado_em?' <span class="status-pill" style="background:#fef3c7;color:#92400e">Editado</span>':'';const pode=p.status==='recebido'||p.podeEditar;const acoes=pode?`<div style="display:flex;gap:8px;margin-top:10px;flex-wrap:wrap"><button class="btn" type="button" onclick="iniciarEdicaoPedido(${p.id})">Editar</button><button class="btn" type="button" style="border-color:#f87171;color:#fca5a5" onclick="cancelarPedido(${p.id})">Cancelar</button></div>`:'';const nItens=(p.itens||[]).reduce((a,it)=>a+(Number(it.quantidade)||1),0);const firstNome=(p.itens&&p.itens[0]&&p.itens[0].nome)?p.itens[0].nome:'Pedido';const quem=p.clienteNome||p.cliente_nome||'';const titulo=quem?`${firstNome} · ${quem}`:firstNome;const isOpen=openIds.has(String(p.id));const openDef=isOpen?' open':'';return `<div class="pedido-block"><details class="pedido-details" data-pedido-id="${p.id}"${openDef}><summary class="pedido-sum"><div class="row" style="justify-content:space-between;gap:8px;width:100%;align-items:flex-start"><b class="pedido-title">${esc(titulo)}</b><span class="pedido-sum-status"><span class="status-pill ${esc(p.status)}">${STATUS_LABEL[p.status]||p.status}</span>${editado}<span class="expand-hint" aria-hidden="true"><span class="expand-chev">▾</span><span class="expand-label">ver itens</span></span></span></div><div class="muted" style="font-size:.8rem;margin-top:4px">${nItens} item${nItens===1?'':'s'} · ${br(p.totalPedido||0)}</div></summary><div class="pedido-body" style="margin-top:10px">${itens}<div class="pedido-item"><span class="muted">Subtotal do pedido</span><b>${br(p.totalPedido||0)}</b></div>${acoes}</div></details></div>`;}).join(''):'<div style="text-align:center;padding:28px;color:#a89f8c">Nenhum pedido ainda.</div>';const pago=Number(s.valorPago||0);const rest=s.valorRestante!=null?Number(s.valorRestante):Math.max(0,Number(s.totalDevido||0)-pago);const totalLine=pago>0.009?`<div class="cart-total-row"><span>Total da conta</span><span>${br(s.totalDevido||0)}</span></div><div class="cart-total-row" style="font-size:.95rem;opacity:.9"><span>Já pago</span><span>${br(pago)}</span></div><div class="cart-total-row"><span>A pagar</span><span>${br(rest)}</span></div>`:`<div class="cart-total-row"><span>Total da conta</span><span>${br(s.totalDevido||0)}</span></div>`;document.getElementById('modal').innerHTML=`<div class="modal-root" role="dialog" aria-modal="true"><div class="modal-backdrop" onclick="closeModal()"></div><div class="modal-sheet conta-sheet"><button class="close" type="button" onclick="closeModal()">×</button><h2>Conta da mesa ${esc(String(s.mesa??''))}</h2>${blocks}<div class="conta-total-block">${totalLine}<p class="muted" style="font-size:.82rem;margin:12px 0 0">Pagamento no caixa ou com o garçom.</p></div></div></div>`;document.body.classList.add('modal-open');window._contaOpenPedidos=Array.from(openIds);lqSaveContaOpen(window._contaOpenPedidos);document.querySelectorAll('.pedido-block details[data-pedido-id]').forEach(function(d){d.addEventListener('toggle',function(){const id=String(d.getAttribute('data-pedido-id'));const set=new Set(window._contaOpenPedidos||[]);if(d.open)set.add(id);else set.delete(id);window._contaOpenPedidos=Array.from(set);});});if(typeof window._afterOpenSessao==='function'){try{window._afterOpenSessao(s);}catch(_){}}requestAnimationFrame(function(){const sheet=document.querySelector('.modal-sheet.conta-sheet');if(sheet&&window._contaSheetScroll!=null){sheet.scrollTop=window._contaSheetScroll;}});}
function togglePedir(){if(cartOpen){closeModal();return;}openCart();}
function toggleConta(){if(sessaoOpen){closeModal();return;}openSessao();}
async function loadCardapio(){const menuEl=document.getElementById('menu');if(menuEl&&!menuEl.innerHTML.trim()){menuEl.innerHTML='<div class="mesa-loading" aria-live="polite"><span class="mesa-loading__spin"></span> Carregando cardápio…</div>';}const pCard=fetch('/api/cardapio').then(async r=>{if(!r.ok)throw new Error('cardapio');return r.json();});const pDest=loadDestaques();try{categorias=await pCard;produtos=categorias.flatMap(c=>c.produtos||[]);renderMenu();}catch(_){if(menuEl)menuEl.innerHTML='<div style="padding:20px;color:#a89f8c">Não foi possível carregar o cardápio.</div>';return;}await pDest;if(typeof renderMenuBody==='function'&&document.getElementById('menuBody'))renderMenuBody();else renderMenu();}
let mesaCatFilter=(function(){try{const v=lqGetJson('lq-mesa-cat-'+lqPageId(),null);return v||'all';}catch(_){return 'all';}})();
let mesaDestaques=null;let mesaDestaquesMsg='';let mesaSearch='';
const FIRST_MSGS=['Parabéns — você é o primeiro cliente do dia. Ainda sem sugestões por aqui!','O dia mal começou e você já chegou: sem ranking ainda, escolha o que der vontade.','Pista livre: ainda não rolou venda hoje. Você abre o placar!','Sugestões do dia? Ainda no forno. Enquanto isso, o cardápio está todo seu.','Silêncio no placar de vendas… por enquanto. Que tal ser o nº 1 de hoje?'];
function randomFirstMsg(){return FIRST_MSGS[Math.floor(Math.random()*FIRST_MSGS.length)];}
async function loadDestaques(){try{const r=await fetch('/api/cardapio/destaques?limit=6');if(!r.ok){mesaDestaques=[];mesaDestaquesMsg=randomFirstMsg();return;}const d=await r.json();const itens=Array.isArray(d.itens)?d.itens:[];mesaDestaques=itens;mesaDestaquesMsg=itens.length?'':randomFirstMsg();}catch(_){mesaDestaques=[];mesaDestaquesMsg=randomFirstMsg();}}
const CAT_ICONS={'Hot Dogs':'🌭','Sanduíches':'🍔','Lanches':'🍔','Porções':'🍟','Bebidas':'🥤','Drinks':'🍸','Drinks Sem Álcool':'🍹','Drinks de Gin':'🍸','Drinks Diversos':'🥂','Caipirinhas':'🍋','Doses':'🥃','Cerveja 600ml':'🍺','Long Neck':'🍺','Cervejas':'🍺','Combos':'🧺','Sobremesas':'🍨','Energéticos':'⚡'};
function demoPhoto(p,catNome){const nome=String(p&&p.nome||'').toLowerCase().normalize('NFD').replace(/\p{M}/gu,'');const cat=String(catNome||(p&&p._catNome)||'').toLowerCase().normalize('NFD').replace(/\p{M}/gu,'');if(/^combo\b|\bcombo\b/.test(nome))return '/assets/demo/combo.webp';if(/dog/.test(nome)&&/bacon/.test(nome))return '/assets/demo/dog-bacon.webp';if(/dog/.test(nome)&&/especial/.test(nome))return '/assets/demo/dog-especial.webp';if(/dog/.test(nome)&&/(vegetariano|vegano)/.test(nome))return '/assets/demo/dog-veg.webp';if(/dog/.test(nome)&&/duplo/.test(nome))return '/assets/demo/dog-duplo.webp';if(/dog/.test(nome)||/hot\s*dogs?/.test(cat))return '/assets/demo/dog-classic.webp';if(/x-?\s*bacon|xbacon/.test(nome))return '/assets/demo/xbacon.webp';if(/x-?\s*salada/.test(nome))return '/assets/demo/salad.webp';if(/x-?\s*tudo/.test(nome))return '/assets/demo/burger.webp';if(/frango grelhado|x-?\s*frango/.test(nome))return '/assets/demo/chicken.webp';if(/misto/.test(nome))return '/assets/demo/misto.webp';if(/natural de frango|sanduiche natural|sanduíche natural/.test(nome))return '/assets/demo/natural.webp';if(/sandu|x-|burger|hamb/.test(nome)||/sandu/.test(cat))return '/assets/demo/burger.webp';if(/onion|anel/.test(nome))return '/assets/demo/onion.webp';if(/batata/.test(nome))return '/assets/demo/fries.webp';if(/passarinho/.test(nome))return '/assets/demo/chicken.webp';if(/polenta/.test(nome))return '/assets/demo/polenta.webp';if(/mandioca|aipim/.test(nome))return '/assets/demo/mandioca.webp';if(/suco/.test(nome))return '/assets/demo/juice.webp';if(/milk\s*shake|milkshake|shake/.test(nome))return '/assets/demo/milkshake.webp';if(/agua de coco|\bcoco\b/.test(nome))return '/assets/demo/water.webp';if(/\bagua\b/.test(nome))return '/assets/demo/water.webp';if(/refrigerante|refri|coca|cola/.test(nome))return '/assets/demo/soda-cola.webp';if(/caipi/.test(nome))return '/assets/demo/caipi.webp';if(/red\s*bull|monster|tnt|baly|energ/.test(nome))return '/assets/demo/energy.webp';if(/long\s*neck|cerveja|chopp|pilsen|malte|\bipa\b|balde/.test(nome))return '/assets/demo/beer.webp';if(/gin|moscow|mule|vodka|drink/.test(nome))return '/assets/demo/cocktail.webp';if(/churros/.test(nome))return '/assets/demo/churros.webp';if(/brownie/.test(nome))return '/assets/demo/brownie.webp';if(/petit|gateau/.test(nome))return '/assets/demo/petit.webp';if(/sobremesa|sorvete|doce/.test(nome)||/sobremesa/.test(cat))return '/assets/demo/dessert.webp';if(/hot\s*dog|dog/.test(cat))return '/assets/demo/dog-classic.webp';if(/sandu/.test(cat))return '/assets/demo/burger.webp';if(/porc/.test(cat))return '/assets/demo/fries.webp';if(/cerveja|chopp|bar/.test(cat))return '/assets/demo/beer.webp';if(/drink/.test(cat))return '/assets/demo/cocktail.webp';if(/bebida/.test(cat))return '/assets/demo/drink.webp';if(/combo/.test(cat))return '/assets/demo/combo.webp';return '/assets/demo/burger.webp';}
function productPhotoUrl(p,catNome){if(p&&p.fotoUrl)return p.fotoUrl;return demoPhoto(p,catNome);}
function setMesaCat(id){mesaCatFilter=String(id||'all');lqSetJson('lq-mesa-cat-'+lqPageId(),mesaCatFilter);renderMenu();}
function setMesaSearch(q){mesaSearch=String(q||'');const box=document.getElementById('mesaSearchBox');if(box)box.classList.toggle('has-value',!!mesaSearch.trim());renderMenuBody();}
function clearMesaSearch(){mesaSearch='';const input=document.getElementById('mesaSearchInput');if(input)input.value='';setMesaSearch('');}
function buildMenuBodyHtml(){const q=mesaSearch.trim().toLowerCase();let sugHtml='';if(!q&&mesaCatFilter==='all'){if(mesaDestaques&&mesaDestaques.length){const cards=mesaDestaques.map(it=>{const full=produtos.find(x=>Number(x.id)===Number(it.id))||it;const foto=productPhotoUrl(full,full._catNome||'');const custom=productNeedsCustom(full);const escolha=productIsEscolha(full,full._catNome||'');let actions;if(escolha){actions=`<button type="button" class="btn-add ghost" onclick="event.stopPropagation();openCustomize(${full.id})">Escolher</button>`;}else if(custom){actions=`<div class="sug-actions"><button type="button" class="btn-add" onclick="event.stopPropagation();quickAdd(${full.id})">+</button><button type="button" class="btn-add ghost" onclick="event.stopPropagation();openCustomize(${full.id})">✎</button></div>`;}else{actions=`<button type="button" class="btn-add" onclick="event.stopPropagation();quickAdd(${full.id})">+ Adicionar</button>`;}return `<article class="sug-card" role="button" tabindex="0" onclick="openProductDetail(${full.id})"><div class="sug-card__media"><img src="${esc(foto)}" alt="" loading="lazy" onerror="this.onerror=null;this.src='/assets/demo/burger.webp'"></div><div class="sug-card__body"><h3>${esc(full.nome||it.nome)}</h3><div class="sug-card__row"><span class="price">${br(full.preco!=null?full.preco:it.preco)}</span>${actions}</div></div></article>`;}).join('');sugHtml=`<section class="mesa-sugestoes"><h2 class="mesa-section-title">Sugestões do dia</h2><div class="mesa-sugestoes__scroll">${cards}</div></section>`;}else if(Array.isArray(mesaDestaques)&&!mesaDestaques.length&&mesaDestaquesMsg){sugHtml=`<p class="mesa-empty" style="margin:8px 0 16px">${esc(mesaDestaquesMsg)}</p>`;}}function cardHtml(p,c){const foto=productPhotoUrl(p,c.nome);const escolha=productIsEscolha(p,c.nome);const custom=productNeedsCustom(p);let actions;if(escolha){actions=`<button class="btn-add ghost" type="button" onclick="event.stopPropagation();openCustomize(${p.id})">Escolher</button>`;}else if(custom){actions=`<div class="prod-actions"><button class="btn-add" type="button" onclick="event.stopPropagation();quickAdd(${p.id})" title="Adicionar" aria-label="Adicionar">+</button><button class="btn-add ghost" type="button" onclick="event.stopPropagation();openCustomize(${p.id})" title="Personalizar">✎</button></div>`;}else{actions=`<button class="btn-add" type="button" onclick="event.stopPropagation();quickAdd(${p.id})" title="Adicionar" aria-label="Adicionar">+</button>`;}return `<article class="prod-card" role="button" tabindex="0" onclick="openProductDetail(${p.id})"><div class="prod-card__media"><img src="${esc(foto)}" alt="" width="320" height="280" loading="lazy" decoding="async" fetchpriority="low" onerror="this.onerror=null;this.src='/assets/demo/burger.webp'"></div><div class="prod-card__body"><h3>${esc(p.nome)}</h3><p class="desc">${esc(p.descricao||'')}</p><div class="prod-card__row"><span class="price">${br(p.preco)}</span>${actions}</div></div></article>`;}let bodyHtml='';if(q){let list=[];for(const c of categorias){for(const p of (c.produtos||[])){p._catNome=c.nome;const hay=(String(p.nome)+' '+String(p.descricao||'')+' '+String(c.nome)).toLowerCase();if(!hay.includes(q))continue;list.push({p,c});}}const cards=list.length?list.map(({p,c})=>cardHtml(p,c)).join(''):'<div class="mesa-empty">Nenhum item encontrado.</div>';bodyHtml=`<h2 class="mesa-section-title">Resultados${list.length?` · ${list.length}`:''}</h2><div class="prod-grid">${cards}</div>`;}else{const cats=categorias.filter(c=>mesaCatFilter==='all'||String(c.id)===String(mesaCatFilter));bodyHtml=cats.map(c=>{const prods=(c.produtos||[]).map(p=>{p._catNome=c.nome;return p;});if(!prods.length)return '';const cards=prods.map(p=>cardHtml(p,c)).join('');const many=prods.length>2;const listClass=many?'prod-scroll prod-scroll--2row':'prod-grid prod-grid--few';return `<section class="cat-section"><div class="cat-section__head"><h2 class="mesa-section-title">${esc(c.nome)}</h2>${many?`<span class="cat-section__hint">deslize →</span>`:''}</div><div class="${listClass}">${cards}</div></section>`;}).join('')||'<div class="mesa-empty">Nenhum item nesta categoria.</div>';}return sugHtml+bodyHtml;}
function renderMenuBody(){const body=document.getElementById('menuBody');if(!body){renderMenu();return;}body.innerHTML=buildMenuBodyHtml();}
function renderMenu(){const chips=[{id:'all',nome:'Todos',ico:'✨'}].concat(categorias.map(c=>({id:String(c.id),nome:c.nome,ico:CAT_ICONS[c.nome]||'🍽️'})));const chipsHtml='<div class="cat-chips" id="mesaCatChips" role="tablist">'+chips.map(ch=>{const on=String(mesaCatFilter)===String(ch.id);return `<button type="button" class="cat-chip${on?' active':''}" role="tab" aria-selected="${on}" onclick="setMesaCat('${esc(ch.id)}')"><span class="chip-ico" aria-hidden="true">${ch.ico}</span><span class="chip-label">${esc(ch.nome)}</span></button>`;}).join('')+'</div>';const q=mesaSearch.trim();const searchHtml=`<div class="mesa-search${q?' has-value':''}" id="mesaSearchBox"><span class="search-ico" aria-hidden="true">🔍</span><input id="mesaSearchInput" type="search" placeholder="Buscar no cardápio…" value="${esc(mesaSearch)}" autocomplete="off" enterkeyhint="search"><button type="button" class="search-clear" aria-label="Limpar busca" onclick="clearMesaSearch()">×</button></div>`;document.getElementById('menu').innerHTML=searchHtml+chipsHtml+'<div id="menuBody">'+buildMenuBodyHtml()+'</div>';const input=document.getElementById('mesaSearchInput');if(input&&!input.dataset.bound){input.dataset.bound='1';input.addEventListener('input',function(){mesaSearch=input.value||'';const box=document.getElementById('mesaSearchBox');if(box)box.classList.toggle('has-value',!!mesaSearch.trim());renderMenuBody();});}}
function openProductDetail(id){const p=produtos.find(x=>Number(x.id)===Number(id));if(!p)return;const escolha=productIsEscolha(p,p._catNome);const custom=productNeedsCustom(p);const foto=productPhotoUrl(p,p._catNome);let actions;if(escolha){actions=`<button class="btn primary btn-chip full" type="button" onclick="closeModal();openCustomize(${p.id})">Escolher opções</button>`;}else if(custom){actions=`<div class="detail-actions"><button class="btn primary btn-chip" type="button" onclick="quickAdd(${p.id});closeModal()">+ Adicionar</button><button class="btn btn-chip" type="button" onclick="closeModal();openCustomize(${p.id})">Personalizar</button></div>`;}else{actions=`<button class="btn primary btn-chip full" type="button" onclick="quickAdd(${p.id});closeModal()">+ Adicionar ao pedido</button>`;}const root=document.getElementById('modal');root.innerHTML=`<div class="modal-root product-detail-root" role="dialog" aria-modal="true"><div class="modal-backdrop product-detail-backdrop" onclick="closeModal()"></div><div class="modal-sheet product-detail-sheet"><button class="close" type="button" onclick="closeModal()" aria-label="Fechar">×</button><div class="product-detail-media"><img src="${esc(foto)}" alt="" width="640" height="440" decoding="async" fetchpriority="high" onerror="this.onerror=null;this.src='/assets/demo/burger.webp'"></div><div class="product-detail-body"><h2>${esc(p.nome)}</h2><p class="muted detail-desc">${esc(p.descricao||'Sem descrição.')}</p><div class="price detail-price">${br(p.preco)}</div>${actions}</div></div></div>`;document.body.classList.add('modal-open');cartOpen=false;sessaoOpen=false;customizeDraft=null;}
function quickAdd(id){const p=produtos.find(x=>x.id===id);if(!p)return;const key=itemKey(id,[],[],'');const existing=cart.find(x=>x.key===key);if(existing)existing.qty+=1;else cart.push({key,productId:id,qty:1,additions:[],removals:[],note:''});updateCartPill();bounceBurger();showToast(p.nome+' adicionado');}
let customizeDraft=null;
function openCustomize(id){const p=produtos.find(x=>x.id===id);if(!p)return;const escolha=productIsEscolha(p);customizeDraft={productId:id,qty:1,additions:[],removals:[],note:'',ponto:null,escolha};if(escolha&&p.adicionais&&p.adicionais.length===1){const a0=p.adicionais[0];customizeDraft.additions=[{id:a0.id,nome:a0.nome,preco:Number(a0.preco)}];}renderCustomizeModal();}
function closeModal(){document.getElementById('modal').innerHTML='';document.body.classList.remove('modal-open');cartOpen=false;sessaoOpen=false;customizeDraft=null;}
(function mesaScrollCompact(){let pinned=false;let searchH=56;let ticking=false;function ensureSpacer(){let sp=document.getElementById('mesaSearchSpacer');if(!sp){sp=document.createElement('div');sp.id='mesaSearchSpacer';sp.setAttribute('aria-hidden','true');sp.style.cssText='display:none;width:100%;pointer-events:none;';}return sp;}function measureSearch(){const box=document.getElementById('mesaSearchBox');if(!box)return 56;const h=box.getBoundingClientRect().height;return h>0?Math.ceil(h):56;}function pinSearch(on){const box=document.getElementById('mesaSearchBox');if(!box)return;const menu=document.getElementById('menu');const sp=ensureSpacer();if(on){if(!pinned){searchH=measureSearch();if(menu&&sp.parentNode!==menu){box.parentNode.insertBefore(sp,box.nextSibling);}sp.style.height=searchH+'px';sp.style.display='block';box.classList.add('is-pinned');pinned=true;}}else if(pinned){box.classList.remove('is-pinned');sp.style.display='none';sp.style.height='0';pinned=false;}}function update(){ticking=false;const y=window.scrollY||document.documentElement.scrollTop||0;const head=document.querySelector('.mesa-sticky-head');const chips=document.getElementById('mesaCatChips')||document.querySelector('.cat-chips');const headH=head?head.offsetHeight:80;const pinAt=Math.max(24,headH*0.55);const t=Math.max(0,Math.min(1,y/Math.max(50,headH)));if(head){head.style.setProperty('--logo-hide',t.toFixed(3));head.classList.toggle('is-scrolled',t>0.08);head.classList.toggle('is-faded',t>0.55);}if(chips){chips.style.setProperty('--logo-hide',t.toFixed(3));chips.classList.toggle('is-scrolled',t>0.08);chips.classList.toggle('is-faded',t>0.55);}pinSearch(y>=pinAt);}function onScroll(){if(ticking)return;ticking=true;requestAnimationFrame(update);}window.addEventListener('scroll',onScroll,{passive:true});window.addEventListener('resize',function(){pinned=false;const box=document.getElementById('mesaSearchBox');if(box)box.classList.remove('is-pinned');update();},{passive:true});document.addEventListener('DOMContentLoaded',update);const _rm=window.renderMenu;if(typeof _rm==='function'){window.renderMenu=function(){pinned=false;_rm.apply(this,arguments);requestAnimationFrame(update);};}update();})();
